entries[132172] = { ["name"] = "Brecheisen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ermöglicht das Öffnen von Schlössern, die eine Fertigkeit von bis zu 550 im Schlossknacken benötigen. Das Brecheisen wird nach 3 Anwendungen verbraucht.\n3 Aufladungen\n\"Ein schwach aussehendes Brecheisen, das vielleicht ein paar Dinge öffnen kann, bevor es zerbricht.\"\nVerkaufspreis:" }
entries[132176] = { ["name"] = "Donner Spezial", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Nehmt einen Schluck von diesem köstlichen, kalten Getränk. Funktioniert nicht bei Spielercharakteren über Stufe 49. (3 Sek. Abklingzeit)\n\"Warnung: Bärte können unter Umständen einen Teil des Getränks aufsaugen.\"" }
