entries[132178] = { ["name"] = "Wetzstein der Schlachtwache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Angriffe haben eine Chance, die Wunden des Ziels freizulegen, wodurch es 100% Waffenschaden als körperlichen Schaden sowie zusätzlich 10 Sek. lang alle 2 Sek. 1 körperlichen Blutungsschaden erleidet. Funktioniert nicht bei Spielercharakteren über Stufe 49. (Procchance: 10%, 2s Abklingzeit) (3 Sek. Abklingzeit)\n\"Abgenutzt, aber glatt. Sehr glatt.\"" }
