entries[132354] = { ["name"] = "Tonikum des Wehrchirurgen", ["text"] = "Wird beim Aufheben gebunden\nWasser Artefaktrelikt\nVerkaufspreis:" }
entries[132355] = { ["name"] = "Windgepeitschter Wehrbannerstreifen", ["text"] = "Wird beim Aufheben gebunden\nSturm Artefaktrelikt\n+ 14 Gegenstands-Level\nVerkaufspreis:" }
entries[132357] = { ["name"] = "Säulen des Dunklen Portals", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 145 / 145\nKlassen: Hexenmeister\nAnlegen: 'Dämonisches Tor' ist für den Träger ein Spontanzauber und kann von ihm ein zweites Mal eingesetzt werden, bevor die Abklingzeit ausgelöst wird.\n\"Nachdem er durch den Dämonenlord Sargeras verderbt wurde, kontaktierte Medivh den orcischen Hexenmeister Gul'dan, und zusammen öffneten sie das Dunkle Portal. So begann die Invasion der Brennenden Legion in Azeroth.\"\nVerkaufspreis:" }
entries[132359] = { ["name"] = "Fesseln des Unterwerfers", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Platte\n8 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 50 / 50\nVerkaufspreis:" }
entries[132360] = { ["name"] = "Versteinerter Arkhana", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[132361] = { ["name"] = "Versteinerter Arkhana", ["text"] = "Artefaktmacht\nWird beim Aufheben gebunden" }
entries[132365] = { ["name"] = "Bryndaors Fesseln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Todesritter\nAnlegen: Wenn Ihr durch 'Todesstoß' um mehr als 10% Eurer maximalen Gesundheit geheilt werdet, erhaltet Ihr 15% der verbrauchten Runenmacht zurück.\n\"Für seine schändlichen Taten wurde Bryndaor verdammt, in alle Ewigkeit an den Toren Helheims Wache zu halten.\"\nVerkaufspreis:" }
entries[132366] = { ["name"] = "Koltiras neugefundener Wille", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 5.\nHaltbarkeit 70 / 70\nKlassen: Todesritter\nAnlegen: 'Auslöschen' verursacht 10% mehr Schaden und hat eine Chance von 15%, 1 Rune zurückzuerstatten. (Procchance: 15%)\n\"Nach der Schlacht an der Kapelle des Hoffnungsvollen Lichts trennten sich die Wege der zwei Kameraden. Thassarian trat in den Dienst seines Königs, während Koltira, vormaliger Verteidiger von Quel'Thalas, zu seinem Volk, den Blutelfen, zurückkehrte.\"\nVerkaufspreis:" }
entries[132367] = { ["name"] = "Dienst von Blutschatten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n+ 3 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 5.\n+ 6 Lebensdiebstahl\nHaltbarkeit 70 / 70\nKlassen: Todesritter\nAnlegen: 'Herzstoß' verringert die verbleibende Abklingzeit von 'Vampirblut' um 2 Sek.\n\"Nach seinem Tod kehrte Blutschatten als erster Todesritter zurück und schwor Orgrim Schicksalshammer die Treue.\"\nVerkaufspreis:" }
entries[132368] = { ["name"] = "Erstes Fragment von Farondis' Band", ["text"] = "Questgegenstand\n\"Ein Bruchstück von Farondis' Band.\"" }
entries[132369] = { ["name"] = "Wilfreds Siegel der überlegenen Beschwörung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure Tempowertung um + 8.\nErhöht Eure Meisterschaftswertung um + 6.\n\nPrismatischer Sockel\n\nKlassen: Hexenmeister\nAnlegen: Jede Beschwörung eines Schreckenspirschers oder Wildwichtels verringert die verbleibende Abklingzeit von 'Dämonischen Tyrannen beschwören' und 'Höllenbestie beschwören' um 2 Sek.\n\"An einem entscheidenden Tag des Argentumturniers zu Hause vergessen.\"\nVerkaufspreis:" }
entries[132370] = { ["name"] = "Salzaugenarmreif", ["text"] = "Questgegenstand\n\"Ein primitiver Ring, passend für Murlocnasenlöcher, -lippen und -flossen.\"" }
entries[132371] = { ["name"] = "Treibholz", ["text"] = "Questgegenstand\n\"Ein Stück sonnengebleichtes Treibholz.\"" }
entries[132374] = { ["name"] = "Kazzaks letzter Fluch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Hexenmeister\nAnlegen: 'Verdammnis' verursacht für jeden Eurer aktiven Dämonenbegleiter 5% höheren Schaden.\n\"Als der Verdammnislord durch das Dunkle Portal in die Scherbenwelt schritt, hinterließ er seinen Feinden ein Abschiedsgeschenk...\"\nVerkaufspreis:" }
entries[132375] = { ["name"] = "Odr, Schal der Ymirjar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 2.\nKlassen: Hexenmeister\nAnlegen: Gegner, die von Eurer 'Verwüstung' markiert wurden, erleiden durch Eure Einzelzielzauber 15% mehr Schaden.\n\"In einwandfreiem Zustand unter dem verbranntem Schutt des Dorfes Ymirheim aufgefunden.\"\nVerkaufspreis:" }
entries[132376] = { ["name"] = "Tuch von Acherus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Stärke\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 4.\nKlassen: Todesritter\nAnlegen: Erhöht die Dauer von 'Antimagische Hülle' um 100%, und jeglicher absorbierter Schaden heilt Euch.\n\"Denn Ihr steht nicht nur mir allein gegenüber, sondern der gesamten Schwarzen Klinge. Wir sind unsterblich, unerbittlich und wir hungern nach Leben!\"\nVerkaufspreis:" }
entries[132377] = { ["name"] = "Aridens Kompass", ["text"] = "Questgegenstand\n\"Ein abgenutzter alter Kompass, der mit den Dunklen Reitern des Gebirgspasses der Totenwinde in Verbindung steht.\"" }
entries[132378] = { ["name"] = "Sacrolashs Dunkelstoß", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 7.\nErhöht Eure Meisterschaftswertung um + 7.\n\nPrismatischer Sockel\n\nKlassen: Hexenmeister\nAnlegen: 'Verderbnis' verursacht 15% mehr Schaden und verringert die Bewegungsgeschwindigkeit von Gegnern um 60%.\n\"Elend... Verwirrung... Misstrauen. Dies sind die Kennzeichen.\"\nVerkaufspreis:" }
entries[132379] = { ["name"] = "Tücke der Sin'dorei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Hexenmeister\nAnlegen: Nach dem Wirken von 'Verdammniswache beschwören', 'Höllenbestie beschwören' oder 'Dämonischen Tyrannen beschwören' verursachen Ihr und Eure Diener 25 Sek. lang 15% mehr Schaden. [ Grimoire der Überlegenheit : Dieser Effekt kann nur einmal alle 3 Min. auftreten ]\n\"So viele unseres Volkes wurden durch die Brennende Legion unterjocht und zu verderbten Schatten ihrer selbst gemacht. Es ist ausgleichende Gerechtigkeit, wenn wir ihre eigenen Armeen gegen sie einsetzen.\"\nVerkaufspreis:" }
entries[132381] = { ["name"] = "Stretens schlaflose Schlingen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Hexenmeister\nAnlegen: Für jeden Gegner, der mit Eurem Zauber 'Instabiles Gebrechen' belegt ist, wird Euer gesamter verursachter Schaden um 4% erhöht.\n\"Das einzige Risiko ist, dass Ihr wahnsinnig werdet.\"\nVerkaufspreis:" }
entries[132393] = { ["name"] = "Regelmäßiges Ritual", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Hexenmeister\nAnlegen: 'Schreckenspirscher rufen' erstattet 1 Seelensplitter zurück.\n\"Es hat Außenstehende schon immer erstaunt, wie einige Vrykulhexenmeister riesige Rudel von Teufelspirschern beschwören und ihrem Willen unterwerfen konnten.\"\nVerkaufspreis:" }
entries[132394] = { ["name"] = "Kapuze der ewigen Verachtung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 120 / 120\nKlassen: Hexenmeister\nAnlegen: 'Agonie' verursacht den vollen Schaden um 10% schneller.\n\"Wer diese Kapuze anlegt, wird von unheiliger Stärke und Entschlossenheit erfüllt. Doch wird er auf ewig alle Freundlichkeit und Güte verlieren. Hütet Euch...\"\nVerkaufspreis:" }
entries[132406] = { ["name"] = "Unvergleichliche Bindungen des Sonnenkönigs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Magier\nAnlegen: Nachdem Ihr 'Kampfeshitze' verbraucht habt, habt Ihr eine Chance von 15%, dass Euer nächster nicht spontaner, innerhalb von 15 Sek. gewirkter 'Pyroschlag' 300% mehr Schaden verursacht.\n\"Entgegen der vorherrschenden Meinung war das bevorzugte (und zumeist auch finale) Wort von Kael'thas an seine Feinde: PYROSCHLAG!\"\nVerkaufspreis:" }
entries[132407] = { ["name"] = "Fesseln des Magiestoßes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Hexenmeister\nAnlegen: 'Chaosblitz' hat eine Chance von 20%, einen weiteren Gegner innerhalb von 30 Metern zu treffen. (Procchance: 20%)\n\"Varo'then war unsterblich in die Königin verliebt. Leider bekam er nie die Gelegenheit, ihr diese Fesseln anzulegen.\"\nVerkaufspreis:" }
entries[132409] = { ["name"] = "Anunds versengte Fesseln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Priester\nAnlegen: Jedes Mal, wenn 'Schattenwort: Schmerz' und 'Vampirberührung' Schaden verursachen, wird der Schaden Eures nächsten Einsatzes von 'Leerenblitz' um 3% erhöht. Bis zu 50-mal stapelbar.\n\"Niemand weiß, warum Anund vor Kaldrigos stand. Laut einer Legende war es aber Anunds letztes 'Schattenwort: Schmerz', das Korl zum Sieg über den schrecklichen Wyrm verhalf.\"\nVerkaufspreis:" }
entries[132410] = { ["name"] = "Splitter der Exodar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 9.\nErhöht Eure Tempowertung um + 5.\n\nPrismatischer Sockel\n\nKlassen: Magier\nAnlegen: Eure Fähigkeit 'Zeitkrümmung' belegt Euch nicht mehr mit dem Effekt 'Temporale Verzerrung' und ignoriert eine bestehende 'Temporale Verzerrung', sowie ähnliche auf Euch aktive Effekte.\n\"Die Hauptstadt der Draenei vermag zwischen den Dimensionen zu reisen und sogar die Zeit selbst zu verzerren. Was könnte ein winziges Fragment dieser Macht wohl alles in den Händen eines Sterblichen bewirken?\"\nVerkaufspreis:" }
entries[132411] = { ["name"] = "Lady Vashjs Griff", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Magier\nAnlegen: Während 'Eisige Adern' aktiv ist, erhaltet Ihr alle 10 Sek. 1 Aufladung von 'Eisige Finger'.\n\"Erfüllt von der Macht der Nagameereshexe fühlen sich Eure Finger darin etwas kalt an, sind aber überraschend beweglich und voller Energie.\"\nVerkaufspreis:" }
entries[132413] = { ["name"] = "Rhonins Angriffsarmwickel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Magier\nAnlegen: 'Arkane Geschosse' haben eine Chance von 18%, dass Euer nächster Einsatz von 'Arkanschlag' innerhalb von 6 Sek. kostenlos wird. (Procchance: 18%)\n\"Magier, die so mächtig sind wie der ehemalige Anführer der Kirin Tor Rhonin, verwenden oft arkane Bindungen, um die Magie zu stabilisieren, die sich aus ihren Fingerspitzen entlädt.\"\nVerkaufspreis:" }
entries[132436] = { ["name"] = "Skjoldr, Ivagonts Refugium", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Priester\nAnlegen: Euer 'Machtwort: Schild' absorbiert 15% mehr Schaden und verringert die verbleibende Abklingzeit von 'Schmerzunterdrückung' um 4 Sek.\n\"Ivagont kämpfte während des Massakers der Sturmschuppennaga an der Dunkelküste so wie immer an der Seite von Kakushan. Durch seinen Schutz überlebten beide ohne einen Kratzer.\"\nVerkaufspreis:" }
entries[132437] = { ["name"] = "Mutter Shahraz' Verführung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Priester\nAnlegen: Wenn Ihr die Leerengestalt annehmt, erhaltet Ihr 3 Stapel von Leerengestalt.\n\"Ihr scheint mir ein wenig verspannt zu sein...\"\nVerkaufspreis:" }
entries[132438] = { ["name"] = "Talisman des Aufstiegs" }
entries[132440] = { ["name"] = "Der Svalngard", ["text"] = "Questgegenstand\n\"Großschild von Odyn, dem Herrn der Hallen der Tapferkeit.\"" }
entries[132441] = { ["name"] = "Draugr, Gurt des ewigen Königs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Todesritter\nAnlegen: 'Schwärender Stoß' hat eine Chance von 30%, 1 Rune zurückzuerstatten. (Procchance: 30%)\n\"Laut einer Legende sind die Körper der Titanenbrut so von der Energie der Schöpfer erfüllt, dass beim Tod des sterblichen Wirts Fragmente zurückbleiben. Angeblich wurde dieser Gurt sorgfältig aus diesen Fragmenten zusammengenäht.\"\nVerkaufspreis:" }
entries[132442] = { ["name"] = "Kordel der Unendlichkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Magier\nAnlegen: Erhöht den von 'Arkane Geschosse' verursachten Schaden um 10%.\nAnlegen: Jedes Mal, wenn 'Arkane Geschosse' einen Gegner trifft, wird der Schaden Eures nächsten Einsatzes von 'Mal von Aluneth' um 1.0% erhöht. Dieser Effekt ist stapelbar.\n\"Die darin enthaltene Magie scheint ebenso wenig ein Ende zu nehmen wie die Brennende Legion.\"\nVerkaufspreis:" }
entries[132443] = { ["name"] = "Aggramars Schritte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Platte\n11 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 95 / 95\nKlassen: Krieger , Paladin , Todesritter\nAnlegen: Erhöht Eure Bewegungsgeschwindigkeit um 75% Eures Tempos, Eures kritischen Trefferwerts, Eurer Meisterschaft oder Eurer Vielseitigkeit, je nachdem, welcher Wert am höchsten ist.\n\"Zeit und Raum sind eins. Für einen Beobachter des Universums ist Entfernung so gut wie bedeutungslos.\"\nVerkaufspreis:" }
entries[132444] = { ["name"] = "Prydaz, Xavarics Magnum Opus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHals\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Tempowertung um + 6.\nErhöht Eure Meisterschaftswertung um + 6.\n\nPrismatischer Sockel\nAnlegen: Verleiht Euch für 30 Sek. alle 30 Sek. einen Absorptionsschild in Höhe von 25% Eurer maximalen Gesundheit.\n\"Träger dieses Amuletts pfeifen eine beunruhigende Melodie, und alle in der Nähe hören zwischen den Noten immer wieder gequälte Schreie, die aus weiter Ferne zu kommen scheinen.\"\nVerkaufspreis:" }
entries[132445] = { ["name"] = "Al'maiesh, der Faden der Hoffnung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 70 / 70\nKlassen: Priester\nAnlegen: Wenn 'Glücksfall' ausgelöst wird und das Segenswort nicht von Abklingzeit betroffen ist, erhöht 'Glücksfall' den Schaden und die Heilung Eures nächsten Einsatzes dieses Segenswortes um 10%. Dieser Effekt ist bis zu 5-mal stapelbar.\n\"Angeblich gehörte sie der ursprünglichen Val'kyr.\"\nVerkaufspreis:" }
entries[132446] = { ["name"] = "Jabruls Juwelen", ["text"] = "Questgegenstand\n\"Ein großer Beutel, der verschiedene Edelsteine enthält.\"" }
entries[132447] = { ["name"] = "Bezaubernde Beinkleider von An'juna", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure Tempowertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 145 / 145\nKlassen: Priester\nAnlegen: Erhöht die Dauer von 'Erneuerung' um 6 Sek.\n\"Die Träger dieser Beinkleider gehen oft bis zum Äußersten und vollbringen mehr, als die Pflicht von ihnen verlangt.\"\nVerkaufspreis:" }
entries[132448] = { ["name"] = "Die vierte Lektion des Instrukteurs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Todesritter\nAnlegen: Geißelstoß hat eine Chance, 1-2 zusätzliche schwärende Wunden aufzubrechen.\n\"Dieses Geschenk übergab Razuvious angeblich seinen begabtesten Akolythen. Aber niemand weiß, wie es aus den Mauern von Naxxramas entkam. Hat der Lichkönig vielleicht seine eigenen Agenten auf die Verheerten Inseln entsandt?\"\nVerkaufspreis:" }
entries[132449] = { ["name"] = "Phyrix' Umarmung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure Tempowertung um + 9.\nErhöht Eure Meisterschaftswertung um + 5.\n\nPrismatischer Sockel\n\nKlassen: Priester\nAnlegen: Erhöht die Dauer und den Heilbonus von 'Schutzgeist' um 50% und der Heilbonuseffekt von 'Schutzgeist' wird nicht mehr abgebrochen, wenn er sich opfert.\n\"Phyrix war eine legendäre Priesterin, die Abenteurer durch den Geschmolzenen Kern und den Pechschwingenhort führte. Leider setzte Nefarian ihrem Leben ein Ende, aber ihr Geist beschützt Azeroths Champions bis zum heutigen Tag.\"\nVerkaufspreis:" }
entries[132450] = { ["name"] = "Muzes standhafter Wille", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Priester\nAnlegen: Wenn Ihr über mehr als 75% Gesundheit verfügt, wird die Zauberzeit Eurer Fähigkeiten 'Blitzheilung', 'Heilung', 'Gebet der Heilung' und 'Heilige Pein' um 15% verringert.\n\"Von ihren bescheidenen Anfängen in Silbermond bis zu den Tiefen des Schwarzfels blieb Muze stets standhaft und brachte dank ihrer Heilkünste ihre Gefährten jedes Mal von der Schwelle des Todes zurück.\"\nVerkaufspreis:" }
entries[132451] = { ["name"] = "Mystischer Kilt des Runenmeisters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure Tempowertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 145 / 145\nKlassen: Magier\nAnlegen: 'Arkanbeschuss' erstattet Euch pro verbrauchter Arkaner Aufladung 3% Eures maximalen Manas zurück.\n\"Obwohl die Halbriesen von Nordend von Natur aus keine oder so gut wie keine Magie verwenden, sind die mystischen Vrykul von Sturmheim wahre Meister der Runenmagie.\"\nVerkaufspreis:" }
entries[132452] = { ["name"] = "Sephuz' Geheimnis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 10.\nErhöht Eure Tempowertung um + 4.\n\nPrismatischer Sockel\nAnlegen: Erhöht Eure Bewegungsgeschwindigkeit um 10% und Euer Tempo um 2%. Wenn Ihr einen Gegner erfolgreich mit einem Kontrollverlusteffekt belegt, ihn unterbrecht oder einen Effekt von einem Ziel bannt, erhöht dieser Effekt stattdessen für 10 Sek. Eure Bewegungsgeschwindigkeit um 70% und Euer Tempo um 25%. Kann nur einmal alle 30 Sek. auftreten.\n\"Die Nichtgreifbarkeit ist ein seltsames Konzept. Das Wort selbst lässt auf eine magische Fähigkeit schließen, aber in der physischen Welt steht es lediglich für die Macht, hier oder dort zu sein, jetzt oder später.\"\nVerkaufspreis:" }
entries[132453] = { ["name"] = "Blutrippenknochenbeinplatten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Platte\n16 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 145 / 145\nKlassen: Todesritter\nAnlegen: 'Knochenschild' erhöht Eure Rüstung zusätzlich um 10% und Eure maximale Runenmacht um 60.\n\"Teile des wandelnden Schreckens Blutrippe sind immer noch von nekromantischer Energie erfüllt, die dem Willen all jener gehorcht, die stark genug sind, sie zu kontrollieren.\"\nVerkaufspreis:" }
entries[132454] = { ["name"] = "Koralons brennende Berührung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Magier\nAnlegen: 'Versengen' verursacht 350% mehr Schaden und trifft Gegner mit weniger als 30% Gesundheit garantiert kritisch.\n\"Tief unten in der von Tausendwinter geschützten Kammer entfachten Eindringlinge stets aufs Neue den Zorn von Koralon dem Flammenwächter.\"\nVerkaufspreis:" }
entries[132455] = { ["name"] = "Norgannons Weitsicht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Priester , Magier , Hexenmeister\nAnlegen: Wenn Ihr Euch 6 Sek. lang nicht bewegt, erhaltet Ihr 'Norgannons Weitsicht'. Diese erlaubt Euch 4 Sek. lang, Zauber aus der Bewegung heraus zu wirken. Die Dauer beginnt, sobald Ihr Euch bewegt.\n\"Magie muss geregelt, verwaltet und kontrolliert werden. Aber sie muss auch geschätzt und in Ehren gehalten werden – nicht gierig gehamstert. Dieses Paradoxon müsst Ihr begreifen.\"\nVerkaufspreis:" }
entries[132456] = { ["name"] = "Bahre der Seelen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Hexenmeister\nAnlegen: Beim Wirken eines Schaden verursachenden Feuerzaubers besteht eine Chance von 6%, einen Seelensplitter zu erzeugen. (Procchance: 6%)\n\"Aus verschiedenen Blickwinkeln betrachtet scheint die schwache Reflektion dreier unterschiedlicher Gesichter zu erkennen zu sein.\"\nVerkaufspreis:" }
entries[132457] = { ["name"] = "Lethtendris' Machtkordel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 5.\nHaltbarkeit 70 / 70\nKlassen: Hexenmeister\nAnlegen: Wenn 'Instabiles Gebrechen' auf ein Ziel gewirkt wird, das noch nicht von 'Instabiles Gebrechen' betroffen ist, besteht eine Chance von 25%, dass Seelensplitterkosten zurückerstattet werden.\n\"Lethtendris erschuf ein Gerät, um die verderbende Macht Düsterbruchs für sich selbst zu nutzen.\"\nVerkaufspreis:" }
entries[132458] = { ["name"] = "Toravons Schneesturmbindungen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Todesritter\nAnlegen: Während 'Säule des Frosts' aktiv ist, wird der verursachte Frostschaden um 15% erhöht.\n\"Tief unten in der von Tausendwinter geschützten Kammer zerschmetterte Toravon der Eiswächter unermüdlich alle Eindringlinge.\"\nVerkaufspreis:" }
entries[132459] = { ["name"] = "Beharrlichkeit des Schwarzen Märtyrers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Platte\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Todesritter\nAnlegen: 'Heulende Böe' fügt Gegnern, die kürzlich Schaden durch Eure Fähigkeit 'Unbarmherziger Winter' erlitten haben, 20% mehr Schaden zu.\n\"Kalter Stahl wiegt schwer auf dem Haupt, das diese Krone trägt.\"\nVerkaufspreis:" }
entries[132460] = { ["name"] = "Alythess' Pyrogenik", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 8.\nErhöht Eure Tempowertung um + 6.\n\nPrismatischer Sockel\n\nKlassen: Hexenmeister\nAnlegen: Durch Euren Zauber 'Feuerregen' betroffene Gegner erleiden um 10% erhöhten Schaden durch Eure Feuerzauber.\n\"Leid... Hass... Chaos. Dies sind die Säulen.\"\nVerkaufspreis:" }
entries[132461] = { ["name"] = "Griff von Xalan dem Gefürchteten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Priester\nAnlegen: Wenn Eure 'Sühne' Schaden verursacht, wird die Effektdauer von 'Abbitte' auf Euch um 3 Sek. erhöht. Wenn sie heilt, wird die Effektdauer von 'Abbitte' stattdessen auf Eurem Ziel um 3 Sek. erhöht.\n\"Während des Kriegs der Satyrn rissen die Nachtelfen Xalan dies glatt aus den Händen.\"\nVerkaufspreis:" }
entries[132462] = { ["name"] = "Donnerhornflanke", ["text"] = "Questgegenstand\n\"Genug Fleisch für die Bäuche von eintausend Kriegern.\"" }
entries[132463] = { ["name"] = "Wirbelsäule des Wirbelschnitters", ["text"] = "Questgegenstand\n\"Aus den Rückgratknochen erwachsener Basilisken kann Brühe für große Mengen Eintopf hergestellt werden.\"" }
entries[132464] = { ["name"] = "Leyhauersteak", ["text"] = "Questgegenstand\n\"Leygetränktes Eberfleisch soll angeblich beim Kochen um das Hundertfache anwachsen.\"" }
entries[132466] = { ["name"] = "Wurzeln von Shaladrassil", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Kette\n10 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 145 / 145\nKlassen: Jäger , Schamane , Rufer\nAnlegen: Wenn Ihr Euch nicht bewegt, schlagt Ihr tiefe Wurzeln in den Boden, die Euch alle 1 Sek. um 3% Eurer maximalen Gesundheit heilen.\n\"Die Bindungen der Erde reichen tief, sind beständig und geraten so gut wie nie ins Wanken.\"\nVerkaufspreis:" }
entries[132467] = { ["name"] = "Vorlage: Himmelssteinanhänger", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Himmelssteinanhängers.\nStellt einen Himmelssteinanhänger her.\nBenötigt Juwelierskunst der Verheerten Inseln\n(1)\n\nHimmelssteinanhänger\nWird beim Anlegen gebunden\nHals\n+4 Ausdauer\n+ 8 Vielseitigkeit\n\nPrismatischer Sockel\n\nVerkaufspreis:\nBenötigt Himmelsstein (5), Azsunit (2), Sangrit\nOptionale Reagenzien: [] (#47)" }
