entries[132859] = { ["name"] = "Delayeths Tagebuch: Die Juwelen der Inseln", ["text"] = "Questgegenstand\n\"Eine täglich geführte Niederschrift von Delayeths Studien, welche die von ihm auf den Verheerten Inseln gefundenen Edelsteine beschreibt sowie die erstaunlichen Muster, nach welchen er sie geschliffen hat.\"" }
