entries[132861] = { ["name"] = "Estel, Dejahnas Inspiration", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Stoff\n5 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 200 / 200\nKlassen: Priester\nAnlegen: Erhöht die hervorgerufene Heilung um 3%.\nAnlegen: 'Bittgebet' erhöht Euer Tempo für jedes Ziel, das mit Eurer Fähigkeit 'Abbitte' belegt ist, 8 Sek. lang um 1%.\n\"Der Glaube ist der Anfang aller Dinge. Ist das Talent für das Arkane zwar vorhanden, aber nicht gefestigt, kann man immer noch Zauberin werden. Aber ist der eigene Glaube lediglich vorhanden und nicht gefestigt, dann wird man niemals Priesterin.\"\nVerkaufspreis:" }
entries[132862] = { ["name"] = "Ring der Gefallenen", ["text"] = "Questgegenstand\n\"In den Ring ist ein schwarzer Opal eingesetzt, dessen neblige Wirbelstruktur etwas Seelenhaftes erkennen lässt.\"" }
entries[132863] = { ["name"] = "Darcklis Drachenfeuerdiadem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Magier\nAnlegen: Erhöht den Schaden von 'Drachenodem' um 100% und die Reichweite um 25 Meter.\n\"Zu den zahllosen Erfolgen von Erzmagier Darckli gehörte auch, dass er mit dem eigenen Mund Drachenfeuer speien konnte.\"\nVerkaufspreis:" }
entries[132864] = { ["name"] = "Mangazas Wahnsinn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Priester\nAnlegen: Erhöht die maximale Anzahl von Aufladungen von 'Gedankenschlag' um 1.\n\"Mangaza der Kaldorei war unter seinen Brüdern für seine Innovationen bekannt, so griff er mit Magie den Verstand seiner Feinde anstelle ihres Körpers an. Leider trieb dies schließlich nicht nur seine Opfer, sondern auch ihn selbst in den Wahnsinn.\"\nVerkaufspreis:" }
